document.addEventListener("DOMContentLoaded",init);async function init(){const slugs=cartStoreSlugs();if(slugs.length===1){location.replace(`cart.html?store=${encodeURIComponent(slugs[0])}`);return}if(slugs.length===0){renderEmpty();return}renderRows(slugs);await hydrateStoreNames(slugs)}function renderEmpty(){document.getElementById("my-carts-status").textContent="";document.getElementById("my-carts-list").innerHTML=`\n    <div class="empty-state">\n      <p>You have no carts yet.</p>\n      <p><a class="btn btn-primary" href="categories.html">Start browsing</a></p>\n    </div>\n  `}function renderRows(slugs){const rows=slugs.map(slug=>{const count=Cart.getItemCount(slug);const total=Cart.getTotal(slug);const noun=count===1?"item":"items";return`\n      <div class="my-cart-row" data-store-slug="${escapeHtml(slug)}">\n        <div class="my-cart-logo-slot" data-logo-for="${escapeHtml(slug)}">\n          <div class="my-cart-logo-placeholder" aria-hidden="true">${escapeHtml(initials(slug))}</div>\n        </div>\n        <div class="my-cart-info">\n          <p class="my-cart-name" data-name-for="${escapeHtml(slug)}">${escapeHtml(slug)}</p>\n          <p class="my-cart-meta">${count} ${noun} · ${escapeHtml(formatMoney(total))}</p>\n          <p class="my-cart-actions">\n            <a class="btn btn-primary btn-small" href="cart.html?store=${encodeURIComponent(slug)}">View Cart</a>\n            <a class="btn btn-small" href="store.html?store=${encodeURIComponent(slug)}">Keep Shopping</a>\n          </p>\n        </div>\n      </div>\n    `}).join("");document.getElementById("my-carts-list").innerHTML=rows;const noun=slugs.length===1?"store":"stores";document.getElementById("my-carts-status").textContent=`You have carts with ${slugs.length} ${noun}. Each store is paid separately.`}async function hydrateStoreNames(slugs){const results=await Promise.all(slugs.map(slug=>Api.get("getStorePublicInfo",{storeSlug:slug}).catch(()=>null)));results.forEach((res,i)=>{if(!res||!res.ok||!res.store)return;const slug=slugs[i];const store=res.store;const nameEl=document.querySelector(`[data-name-for="${CSS.escape(slug)}"]`);if(nameEl&&store.storeName)nameEl.textContent=store.storeName;if(!store.logoUrl)return;const slot=document.querySelector(`[data-logo-for="${CSS.escape(slug)}"]`);if(!slot)return;const img=document.createElement("img");img.className="my-cart-logo";img.src=optimizedImageUrl(store.logoUrl,IMG_W.logo);img.alt="";img.loading="lazy";img.decoding="async";slot.replaceChildren(img)})}